const rows = $input.all().map(i => i.json).filter(r => r && (r.Farm || r.farm));

const cleanNumber = (v) => {
  const n = Number(String(v ?? 0).replace(/,/g, '').replace('%', '').trim());
  return Number.isFinite(n) ? n : 0;
};

const farmName = r => r.Farm || r.farm || 'Unknown Farm';
const cropName = r => r.Crop || r.crop || 'Unknown';
const risk = r => String(r.AI_Risk || r.ai_risk || '').toUpperCase();
const decision = r => String(r.AI_Decision || r.ai_decision || '').toUpperCase();

const totalRecords = rows.length;
const farms = [...new Set(rows.map(farmName))];
const crops = [...new Set(rows.map(cropName))];

const highRisk = rows.filter(r => risk(r) === 'HIGH');
const mediumRisk = rows.filter(r => risk(r) === 'MEDIUM');
const irrigation = rows.filter(r => decision(r) === 'IRRIGATE');

const sum = field => rows.reduce((s, r) => s + cleanNumber(r[field]), 0);
const avg = field => totalRecords ? +(sum(field) / totalRecords).toFixed(2) : 0;

const farmMap = {};

for (const r of rows) {
  const farm = farmName(r);

  if (!farmMap[farm]) {
    farmMap[farm] = {
      farm,
      region: r.Region || r.region || 'Unknown',
      crop: cropName(r),
      records: 0,
      highRisk: 0,
      mediumRisk: 0,
      irrigation: 0,
      water: 0,
      energy: 0,
      soil: 0,
      leaf: 0,
      temperature: 0,
      humidity: 0
    };
  }

  const f = farmMap[farm];

  f.records++;
  if (risk(r) === 'HIGH') f.highRisk++;
  if (risk(r) === 'MEDIUM') f.mediumRisk++;
  if (decision(r) === 'IRRIGATE') f.irrigation++;

  f.water += cleanNumber(r.Estimated_Water_Liters);
  f.energy += cleanNumber(r.Estimated_Energy_kWh);
  f.soil += cleanNumber(r.Soil_Moisture_pct);
  f.leaf += cleanNumber(r.Leaf_Health_pct);
  f.temperature += cleanNumber(r.Temperature_C);
  f.humidity += cleanNumber(r.Humidity_pct);
}

const farmAnalysis = Object.values(farmMap).map(f => ({
  farm: f.farm,
  region: f.region,
  crop: f.crop,
  records: f.records,
  highRisk: f.highRisk,
  mediumRisk: f.mediumRisk,
  irrigation: f.irrigation,
  water_liters: Math.round(f.water),
  energy_kwh: +f.energy.toFixed(2),
  avg_soil_moisture: +(f.soil / f.records).toFixed(1),
  avg_leaf_health: +(f.leaf / f.records).toFixed(1),
  avg_temperature: +(f.temperature / f.records).toFixed(1),
  avg_humidity: +(f.humidity / f.records).toFixed(1)
}));

const priorityFarms = [...farmAnalysis]
  .sort((a, b) => {
    if (b.highRisk !== a.highRisk) return b.highRisk - a.highRisk;
    return a.avg_soil_moisture - b.avg_soil_moisture;
  })
  .slice(0, 8);

const waterConsumers = [...farmAnalysis]
  .sort((a, b) => b.water_liters - a.water_liters)
  .slice(0, 5);

const decisionCounts = {};

for (const r of rows) {
  const d = decision(r) || 'UNKNOWN';
  decisionCounts[d] = (decisionCounts[d] || 0) + 1;
}

const analysis = {
  total_records: totalRecords,
  total_farms: farms.length,
  total_crops: crops.length,
  high_risk_events: highRisk.length,
  medium_risk_events: mediumRisk.length,
  irrigation_events: irrigation.length,
  total_water_liters: Math.round(sum('Estimated_Water_Liters')),
  total_energy_kwh: +sum('Estimated_Energy_kWh').toFixed(2),
  average_temperature: avg('Temperature_C'),
  average_humidity: avg('Humidity_pct'),
  average_soil_moisture: avg('Soil_Moisture_pct'),
  average_leaf_health: avg('Leaf_Health_pct'),
  decisions: decisionCounts,
  priority_farms: priorityFarms,
  top_water_consumers: waterConsumers
};

return [{ json: { analysis } }];

const input = $input.first().json;
const analysis = $('📈 Farm Analytics Engine').first().json.analysis;

let raw = input.output ?? input.text ?? input.response ?? input.message ?? input;

if (typeof raw === 'object') {
  raw = raw.output ?? raw.text ?? raw.response ?? raw;
}

let ai;

function fallback() {
  const critical = Number(analysis.high_risk_events || 0) > 0;

  return {
    executive_status: critical ? 'CRITICAL' : 'HEALTHY',
    critical_alert: critical,
    headline: critical ? 'Critical agricultural risk detected' : 'Farm conditions are stable',
    summary: critical
      ? `${analysis.high_risk_events} high-risk events were detected across the monitored farms.`
      : 'No high-risk events were detected in the supplied dataset.',
    priority_farms: (analysis.priority_farms || []).slice(0, 8).map(f => ({
      farm: f.farm,
      priority: f.highRisk > 0 ? 'HIGH' : 'MEDIUM',
      reason: `High risk events: ${f.highRisk}; soil moisture: ${f.avg_soil_moisture}%`,
      action: f.avg_soil_moisture < 30 ? 'Inspect irrigation conditions' : 'Continue monitoring'
    })),
    recommendations: [
      'Inspect high-risk farms first.',
      'Review irrigation requirements in low-moisture zones.',
      'Monitor water consumption and field conditions.'
    ],
    water_efficiency_note: `Total estimated water consumption is ${analysis.total_water_liters} liters. Review the highest-consuming farms for optimization.`,
    email_message: critical
      ? 'Urgent review is recommended for the farms identified above.'
      : 'No urgent intervention is required based on the current dataset.'
  };
}

try {
  let text = typeof raw === 'string' ? raw : JSON.stringify(raw);

  text = text
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1) {
    text = text.substring(firstBrace, lastBrace + 1);
  }

  ai = JSON.parse(text);
} catch (e) {
  ai = fallback();
}

const boolValue = value => {
  if (value === true) return true;
  if (value === false) return false;
  return ['true', '1', 'yes', 'critical', 'urgent'].includes(String(value).toLowerCase());
};

ai.critical_alert = boolValue(ai.critical_alert);

if (!ai.executive_status) {
  ai.executive_status = ai.critical_alert ? 'CRITICAL' : 'HEALTHY';
}

if (!Array.isArray(ai.priority_farms)) ai.priority_farms = [];
if (!Array.isArray(ai.recommendations)) ai.recommendations = [];

return [{
  json: {
    analysis,
    ai
  }
}];
